// Package licences carries the licence inventory the workbench shows under
// Help > Licences & attributions.
//
// licences.json is generated by tools/licgen and committed, so a dev build is
// never a stub and the CI freshness check (regenerate, diff) is what keeps it
// honest. The curated half lives in docs/licences.json; the Go half is read
// from the build graph.
package licences

import (
	_ "embed"
	"encoding/json"
)

//go:generate go run ../../../tools/licgen

// Entry is one thing the application ships under.
type Entry struct {
	Name    string `json:"name"`
	Detail  string `json:"detail,omitempty"`
	Licence string `json:"licence"`
	Link    string `json:"link,omitempty"`
	Text    string `json:"text,omitempty"`
}

// Section is one group; file order is window order, forks before everything
// third-party because they are modified code.
type Section struct {
	Key     string  `json:"key"`
	Title   string  `json:"title"`
	Blurb   string  `json:"blurb,omitempty"`
	Entries []Entry `json:"entries"`
}

// File is the whole inventory.
type File struct {
	Sections []Section `json:"sections"`
}

//go:embed licences.json
var raw []byte

// Load parses the embedded inventory.
func Load() (File, error) {
	var f File
	err := json.Unmarshal(raw, &f)
	return f, err
}
